  insert into questions (chapter_id, type, category, source, difficulty, stem_md, options_json, answer_key_md, marks, family, explanation_md)
  values
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How many particles are in one mole of a substance?', '["6.022 x 10²³","6.022 x 10²²","1.66 x 10⁻²⁴","6.022 x10¹³"]'::jsonb, 'A', 1, 'f15076a7d0d9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the relationship between mass, moles, and molar mass?', '["Moles = Mass x Molar Mass","Molar Mass = Mass x Moles","Mass = Moles x Molar Mass","Mass = Moles / Molar Mass"]'::jsonb, 'C', 1, 'fbcd7aa017ee', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does a chemical equation with state symbols represent?', '["Only the reactants.","The stoichiometry of the reaction and the physical state of all components.","The time taken for the reaction.","Only the products."]'::jsonb, 'B', 1, '0bfd7f24288a', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In a chemical equation, what do the coefficients indicate?', '["The number of grams.","The molar mass.","The number of moles reacting.","The number of atoms."]'::jsonb, 'C', 1, '5d6447e29f1d', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A binary compound is formed from ions Na⁺ and Cl⁻. What is its formula?', '["Na₂Cl","NaCl","Na₂Cl₂","NaCl₂"]'::jsonb, 'B', 1, 'afe4261bcba9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the simplest formula of a molecule containing C₆H₁₂O₆?', '["C₆H₁₂O₆","C₂H₄O₂","C₃H₆O₃","CH₂O"]'::jsonb, 'D', 1, '25b01cdf57a9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'If you have 0.5 moles of O₂, how many molecules of O₂ do you have?', '["6.022×10²³","3.011×10²³","0.5","1.204×10²⁴"]'::jsonb, 'B', 1, '983d474b162e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does the formula of a binary compound like MgCl₂ tell us?', '["It has 2 Magnesium atoms.","Magnesium has a -2 charge.","It is a covalent molecule.","It has a ratio of 1 Magnesium ion to 2 Chloride ions."]'::jsonb, 'D', 1, 'e137a4dc9e2c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which is a reactant in the following equation? C+O₂→CO₂', '["CO₂","C and O₂","O₂","C"]'::jsonb, 'B', 1, 'cb724c9b5693', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of the following equations is balanced?', '["N₂+H₂→NH₃","N₂+H₂→2NH₃","N₂+3H₂→2NH₃","2N₂+H₂→NH₃"]'::jsonb, 'C', 1, '436be9905e4c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does the state symbol "(s)" indicate in a chemical equation?', '["The substance is in a solid state.","The substance is dissolved in water.","The substance is in a liquid state.","The substance is a solution."]'::jsonb, 'A', 1, '35cdf729d03c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the mole considered a "bridge" in stoichiometry?', '["It counts electrons only.","It is used to balance ionic charges.","It connects the microscopic world of atoms/molecules to the macroscopic world of grams.","It is the only unit that measures volume."]'::jsonb, 'C', 1, '9bae10305ee7', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'If you double the amount of moles of a reactant in a balanced equation, what happens to the theoretical amount of product?', '["It stays the same.","It doubles.","It is halved.","It becomes zero."]'::jsonb, 'B', 1, 'be6cbee568c1', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How does the Law of Conservation of Mass dictate chemical equation balancing?', '["Atoms must be created to balance charge.","Mass can be destroyed if the energy is high enough.","Only the products have mass.","The total mass of reactants must equal the total mass of products, requiring the same number of each type of atom on both sides."]'::jsonb, 'D', 1, '23ee368ae14e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which of these contains the largest number of atoms?', '["1 mole of H₂O","1 mole of NaCl","1 mole of CH₄","1 mole of CO₂"]'::jsonb, 'C', 1, 'fa45ee118e01', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If a reaction equation is A+2B→C, and you have 2 moles of A and 2 moles of B, which is the limiting reactant?', '["A","B","Both are consumed equally.","C"]'::jsonb, 'B', 1, '7e205b3ed9ab', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How many moles of Hydrogen atoms are in 0.5 moles of NH₃?', '["0.5","1.0","1.5","3.0"]'::jsonb, 'C', 1, '16464b46e9cb', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which measurement is not necessary to find the empirical formula of a compound?', '["The mass percentage of each element.","The atomic masses of the elements.","The ratio of the moles of elements.","The molar mass of the compound."]'::jsonb, 'D', 1, 'c2f99e3766e7', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does a molar mass of 18.02 g/mol tell you physically?', '["That 1 molecule weighs 18.02g.","That the element is a solid.","That 6.022×10²³molecules weigh 18.02 g.","That 1 atom weighs 18.02 g."]'::jsonb, 'C', 1, 'c39f10079eaa', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How many grams of Carbon are in 1 mole of Carbon?', '["1g","12g","6g","24g"]'::jsonb, 'B', 1, '4b227c6794ac', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'How many atoms are in one molecule of H₂SO₄?', '["3","6","7","4"]'::jsonb, 'C', 1, '1b8e62927124', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What is the empirical formula of a compound with 40% Carbon, 6.7% Hydrogen, and 53.3% Oxygen?', '["CH₂O","C₂H₄O₂","CHO","C₃H₆O₃"]'::jsonb, 'A', 1, '55532fcb47f8', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why can''t we determine the molecular formula from just the empirical formula?', '["Because the elements are different.","Because the molar mass of the actual compound might be a multiple of the empirical formula''s mass.","Because empirical formulas don''t use real numbers.","Because ratios are wrong."]'::jsonb, 'B', 1, 'b31f48f54725', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the "mole" a better unit than "gram" for chemical reactions?', '["Moles represent the actual count of reactive units, whereas grams depend on atomic mass.","Grams are too small.","Moles are easier to measure.","Grams are not used in science."]'::jsonb, 'A', 1, '153de621814b', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is an empirical formula used for ionic compounds?', '["Because they are too heavy.","Because they have no ratio.","Because they are covalent.","Because they form infinite lattices, not discrete molecules."]'::jsonb, 'D', 1, '2c4002bc0a81', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You have a compound with the empirical formula CH₂. If the molar mass of the actual molecular compound is 84 g/mol, what is the molecular formula?', '["C₂H₄","C₄H₈","C₆H₁₂","C₃H₆"]'::jsonb, 'C', 1, '3951d48fbcfb', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'In the combustion of CH₄ (CH₄+2O₂→CO₂+2H₂O), if you have 1 mole of each reactant, which is the limiting reactant and why?', '["CH₄, because it has fewer moles.","O₂, because the stoichiometric ratio requires 2 moles of O₂for every 1 mole of CH₄.","CH₄, because it is heavier.","O₂, because it is a gas."]'::jsonb, 'B', 1, '87e9f94f66e0', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why do we use ionic equations instead of full molecular equations in aqueous reactions?', '["Because state symbols are not used in ionic equations.","To save ink.","Because molecular equations are always wrong.","To highlight the specific ions that undergo chemical change, ignoring spectator ions."]'::jsonb, 'D', 1, '9969102f6f8e', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You are performing a synthesis where the balanced equation is A+3B→2C. You mix 4 moles of A with 9 moles of B. After the reaction goes to completion, which species are present in the beaker?', '["Only product C","Product C and excess reactant B","Product C and excess reactant A","Only reactant B"]'::jsonb, 'C', 1, 'e0523aefec33', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You have two beakers. Beaker 1 contains 1mol of NaCl. Beaker 2 contains 1mol of CaCl₂. If you add excess AgNO₃ to both to precipitate AgCl, which beaker produces more precipitate, and by what factor?', '["Beaker 1; 1:1 ratio.","Beaker 2; produces twice as much AgCl because it has 2 moles of Cl⁻ ions per mole of compound.","Beaker 2; produces 3 times as much.","Beaker 1; produces twice as much."]'::jsonb, 'B', 1, '114afb9e3a8c', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is it impossible to determine the molecular formula of a hydrocarbon knowing only the percentage composition by mass?', '["Because percentage composition only gives the ratio, not the total molar mass required for the molecular formula.","Because mass percentages are always wrong.","Because hydrocarbons don''t have molecular formulas.","Because the molar mass of Carbon is variable."]'::jsonb, 'A', 1, '70a4e72106df', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'You have a sample of H₂O and D₂O (Heavy water). They have the same number of moles, but different masses. Why?', '["D₂O is a gas.","D₂O has more electrons.","H₂O Is ionic.","D₂O has more neutrons."]'::jsonb, 'D', 1, '082164fc95e8', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'What does the coefficient "3" in 3O₂ represent in a chemical equation?', '["3 grams of oxygen.","3 moles of O₂ molecules.","3 atoms of oxygen.","3 moles of oxygen atoms."]'::jsonb, 'B', 1, '919e8424c3a0', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the atomic mass of Carbon 12.01 and not exactly 12?', '["Measurement errors.","Electrons have mass.","It includes isotopes like C-13 and C-14.","Carbon is an ion."]'::jsonb, 'C', 1, '5a659250393a', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Why is the equation H₂ + O₂ → H₂O considered incorrect?', '["Hydrogen is a metal","Oxygen should be monatomic","Water cannot be formed","Atoms are not balanced"]'::jsonb, 'D', 1, 'b075c44a5092', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which balanced equation is correct?', '["Fe + O₂ → Fe₂O₃","4Fe + 3O₂ → 2Fe₂O₃","2Fe + O₂ → Fe₂O₃","2Fe + 3O₂ → 2Fe₂O₃"]'::jsonb, 'B', 1, '6b2259e3dda9', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which change would NOT affect the validity of a balanced equation?', '["Multiplying all coefficients by the same number","Removing coefficients","Changing subscripts","Changing formulas"]'::jsonb, 'A', 1, '8d323a212f33', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student calculates the molar mass of CaCO₃ as 100 g/mol. Which step is essential in this calculation?', '["Using atomic numbers","Multiplying by Avogadro’s number","Adding the relative atomic masses of all atoms in the formula","Dividing by the number of atoms"]'::jsonb, 'C', 1, '05488eafe8de', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'During a reaction, the total number of molecules changes, but the equation remains balanced. Which law is still obeyed?', '["Conservation of energy","Boyle’s law","Charles’s law","Conservation of mass"]'::jsonb, 'D', 1, 'fe223c9f5790', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When balancing equations, why is it often useful to balance oxygen and hydrogen atoms last?', '["They are usually monatomic.","They often appear in multiple compounds and are easier to adjust later.","They never affect the coefficients of other substances.","Their coefficients are always one."]'::jsonb, 'B', 1, '49eedd98ebde', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A compound contains calcium and nitrogen. Calcium forms Ca²⁺ ions, and nitrogen forms N³⁻ ions. What formula will the compound have?', '["CaN","Ca₂N₃","CaN₂","Ca₃N₂"]'::jsonb, 'D', 1, '0bddee724de7', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'While solving a stoichiometry problem, a student converts mass to moles before using the balanced equation. Why is this step necessary?', '["Balanced equations relate particles and moles, not masses directly.","Moles are always equal to grams.","Mass is conserved only after conversion.","Avogadro’s number cannot be used with grams."]'::jsonb, 'A', 1, '0e43fc0a1ab6', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student notices that ionic equations include aqueous ions but omit solid precipitates. Why?', '["Solids do not dissociate into ions in solution.","Solids do not participate in reactions.","Solids have no charge.","Solids are always spectator ions."]'::jsonb, 'A', 1, '240c2364be9a', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A chemist needs to prepare a neutral compound from Al³⁺ and SO₄²⁻ ions. Which formula is correct?', '["AlSO₄","Al₂(SO₄)₃","Al₃SO₄","Al(SO₄)₂"]'::jsonb, 'B', 1, 'd06f4122549d', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A student compares one mole of oxygen gas with one mole of oxygen atoms. Which statement is correct?', '["Both contain the same number of atoms.","Oxygen atoms contain twice as many molecules.","Both have different Avogadro numbers.","Oxygen gas contains twice as many oxygen atoms."]'::jsonb, 'D', 1, '9af517289d45', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'If a reaction has a theoretical yield of 50g and an actual yield of 40g, what is the percentage yield, and what does this imply?', '["80%; it implies incomplete reaction or losses during separation.","20%; it implies the reaction is efficient.","100%; yield is always theoretical.","40%; it implies the reaction was too fast."]'::jsonb, 'A', 1, '7c8732cc8c5b', null),
    (v_chapter, 'mcq', 'scenario', 'bank', 3, 'A chemist writes the molecular equation for a reaction, but the net ionic equation is much shorter. Why?', '["Molecular equations are always incorrect.","Net ionic equations ignore charges.","Molecular equations contain only solids.","Net ionic equations include only substances that actually change during the reaction."]'::jsonb, 'D', 1, '12fc26adf9b1', null),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'Which statement best explains why coefficients are used instead of changing subscripts when balancing equations?', '["Subscripts represent fixed chemical identities of substances","Coefficients cannot be changed","Subscripts represent masses only","Coefficients change the formula"]'::jsonb, 'A', 1, '73489b77a598', null);
